import argparse,copy,hashlib,json,math,pathlib,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--out',required=True);a=p.parse_args();root=ET.parse(a.source).getroot();ix={(e.tag,e.get('id')):e for e in root}
relation=ix['relation','5862584'];outer=[ix['way',m.get('ref')]for m in relation.findall('member')if m.get('role')=='outer'];pieces=[[n.get('ref')for n in w.findall('nd')]for w in outer];ring=pieces.pop(0)
while pieces:
 for i,part in enumerate(pieces):
  if ring[-1]==part[0]:ring+=part[1:];pieces.pop(i);break
  if ring[-1]==part[-1]:ring+=part[-2::-1];pieces.pop(i);break
 else:raise ValueError('Unclosed mapped outer boundary')
assert ring[0]==ring[-1]
ways=outer+[ix['way','137725307'],ix['way','45099263']];ids=set(n.get('ref')for w in ways for n in w.findall('nd'));subset=ET.Element('osm',version='0.6',generator='j3k-frozen-selected-outer-and-platform-reference')
for id in sorted(ids,key=int):subset.append(copy.deepcopy(ix['node',id]))
