subset.append(copy.deepcopy(relation))
source=ET.tostring(subset,encoding='utf-8',xml_declaration=True);out=pathlib.Path(a.out);out.mkdir(parents=True,exist_ok=True);(out/'data/urban/sources').mkdir(parents=True,exist_ok=True);(out/'data/urban/sources/haram-court.osm.xml').write_bytes(source)
def point(id):
 n=ix['node',id];return [float(n.get('lat')),float(n.get('lon'))]
def area(points):
 q=[((lon-35.235)*math.pi/180*6378137*math.cos(math.radians(31.778)),-(lat-31.778)*math.pi/180*6378137)for lat,lon in points];return abs(sum(x*z2-x2*z for (x,z),(x2,z2)in zip(q,q[1:]+q[:1])))/2
footprint=[point(id)for id in ring[:-1]];podium=[point(n.get('ref'))for n in ix['way','137725307'].findall('nd')][:-1];chain=[point(n.get('ref'))for n in ix['way','45099263'].findall('nd')][:-1]
data={'schema':'j3k.haram-court-reference.v1','source':{'url':'https://api.openstreetmap.org/api/0.6/map?bbox=35.222,31.770,35.242,31.785','sha256':hashlib.sha256(source).hexdigest(),'rawSubset':'data/urban/sources/haram-court.osm.xml','attribution':'OpenStreetMap contributors, ODbL'},'relation':5862584,'outerWays':[int(w.get('id'))for w in outer],'footprint':footprint,'podiumWay':137725307,'podium':podium,'chainWay':45099263,'chainPoint':[sum(p[i]for p in chain)/len(chain)for i in [0,1]],'mappedAreaSquareMetres':area(footprint),'historicalGeometryVerified':False}
(out/'haram-court-reference.js').write_text('// Generated by scripts/ingest_jerusalem_3000_haram_reference.py; frozen modern map context, not historical survey.\nexport const haramCourtReference = '+json.dumps(data,ensure_ascii=True,indent=2)+';\n',encoding='utf-8');print(json.dumps({'area':data['mappedAreaSquareMetres'],'nodes':len(footprint),'upperArea':area(podium)}))
